from pathlib import Path

md_path = Path("E:/AURA/aura-main/MANUSCRIPT_FINAL_npjDM.md")
md_text = md_path.read_text(encoding="utf-8")

old_abstract = """Empirical claims that quantum machine learning outperforms classical models have proliferated in digital health, yet comparison symmetry is rarely audited. We evaluated whether reported quantum benefits survive symmetric evaluation requiring matched optimization, independent calibration, leak-free partitioning, and resampled inference. In a chest radiograph triage prototype across 56,534 held-out patients, default variational quantum circuits (VQC) yielded higher negative log-likelihood ($\Delta\text{NLL} = +0.0205$ nats; 10-seed mean $+0.0142$ nats) than matched classical baselines, exceeding seed variance ($\sigma_{\text{seed}} = 0.0045$ nats). Under matched 36-configuration search, optimal VQC test loss was statistically equivalent to classical baselines overall ($\Delta\text{NLL} = -0.0026$ nats; 10-seed mean $-0.00067$ nats, $\pm 0.010$ margin), but equivalence failed under class-balanced macro-averaging ($\Delta\text{NLL}_{\text{macro}} = +0.0389$ nats, $p_{\text{TOST}} > 0.99$; Malignancy $+0.1771$ nats), while requiring 92.8-fold more compute. Classical polynomial (NLL 1.1092) and Fourier surrogates (NLL 1.1123) outperformed the tuned VQC (1.1144). Under institutional transfer, all models degraded ($\Delta\text{NLL} = +0.131$ to $+0.197$ nats). Across five reconstructible publications spanning six clinical tasks, none of six published claims were verified: one was not reproduced, one collapsed to chance (52.1%), and four were statistically inconclusive. Reported quantum benefits reflected evaluation asymmetries, uncalibrated comparisons, or underpowered cohorts rather than verified algorithmic superiority."""

new_abstract = """Empirical claims that quantum machine learning outperforms classical models have proliferated in digital health, yet comparison symmetry is rarely audited. We evaluated whether reported quantum benefits survive symmetric evaluation requiring matched optimization, independent calibration, leak-free partitioning, and resampled inference. In a chest radiograph triage prototype across 56,534 held-out patients, default variational quantum circuits (VQC) yielded higher negative log-likelihood ($\Delta\text{NLL} = +0.0205$ nats; 10-seed mean $+0.0142$ nats) than matched classical baselines, exceeding seed variance ($\sigma_{\text{seed}} = 0.0045$ nats). Under matched 36-configuration search, optimal VQC test loss was statistically equivalent to classical baselines overall ($\Delta\text{NLL} = -0.0026$ nats; 10-seed mean $-0.00067$ nats, $\pm 0.010$ margin), but equivalence failed under class-balanced macro-averaging ($\Delta\text{NLL}_{\text{macro}} = +0.0389$ nats, $p_{\text{TOST}} > 0.99$; Malignancy $+0.1771$ nats), while requiring 92.8-fold more compute. Classical polynomial (NLL 1.1092) and Fourier surrogates (NLL 1.1123) outperformed the tuned VQC (1.1144). Under institutional transfer, the quantum circuit trailed classical baselines by $\Delta\text{NLL} = +0.1589$ to $+0.1967$ nats. Across five reconstructible publications spanning six clinical tasks, none of six published claims were verified: one was not reproduced, one collapsed to chance (52.1%), and four were statistically inconclusive. Reported quantum benefits reflected evaluation asymmetries, uncalibrated comparisons, or underpowered cohorts rather than verified algorithmic superiority."""

